	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void idleTupleResultDeadlineClosesUnconsumedDelegate() throws Exception {
		CountDownLatch deadlineExpired = new CountDownLatch(1);
		AtomicReference<QueryExecutionDeadline> deadlineRef = new AtomicReference<>();
		BlockingIteration iteration = new BlockingIteration();
		when(sailConnection.evaluate(any(), any(), any(), anyBoolean())).thenAnswer(invocation -> {
			QueryExecutionDeadline deadline = QueryExecutionDeadline.current();
			if (deadline == null) {
				throw new AssertionError("Sail evaluation must inherit the public query deadline");
			}
			deadlineRef.set(deadline);
			deadline.onExpiration(deadlineExpired::countDown);
			return iteration;
		});

		TupleQuery query = repositoryConnection.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o }");
		query.setMaxExecutionTime(MAX_EXECUTION_TIME_SECONDS);
		TupleQueryResult result = query.evaluate();
		try {
			assertThat(deadlineRef.get()).isNotNull();
			assertThat(deadlineExpired.await(3, TimeUnit.SECONDS)).isTrue();
			assertThat(iteration.closedLatch.await(1, TimeUnit.SECONDS))
					.as("deadline expiry must eventually close the idle delegate")
					.isTrue();
			assertThat(iteration.closed.get())
					.as("expiration must release resources even when the public result is idle")
					.isTrue();
		} finally {
			result.close();
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void deadlineExpiryClosesIdleDelegateWithoutBlockingOtherDeadlines() throws Exception {
		CountDownLatch firstDeadlineExpired = new CountDownLatch(1);
		CountDownLatch releaseFirstClose = new CountDownLatch(1);
		BlockingIteration first = new BlockingIteration();
		first.blockClose(releaseFirstClose);
		BlockingIteration second = new BlockingIteration();
		AtomicReference<QueryExecutionDeadline> firstDeadline = new AtomicReference<>();
		AtomicInteger evaluationCount = new AtomicInteger();
		when(sailConnection.evaluate(any(), any(), any(), anyBoolean())).thenAnswer(invocation -> {
			BlockingIteration iteration = evaluationCount.getAndIncrement() == 0 ? first : second;
			QueryExecutionDeadline deadline = QueryExecutionDeadline.current();
			if (deadline == null) {
				throw new AssertionError("Sail evaluation must inherit the public query deadline");
			}
			if (iteration == first) {
				firstDeadline.set(deadline);
				deadline.onExpiration(firstDeadlineExpired::countDown);
			}
			return iteration;
		});

		TupleQuery firstQuery = repositoryConnection.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o }");
		firstQuery.setMaxExecutionTime(MAX_EXECUTION_TIME_SECONDS);
		TupleQueryResult firstResult = firstQuery.evaluate();
		try {
			assertThat(firstDeadlineExpired.await(3, TimeUnit.SECONDS)).isTrue();
			assertThat(first.closeEntered.await(1, TimeUnit.SECONDS))
					.as("idle deadline cleanup should begin on an independent worker")
					.isTrue();

			TupleQuery secondQuery = repositoryConnection.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o }");
			secondQuery.setMaxExecutionTime(MAX_EXECUTION_TIME_SECONDS);
			TupleQueryResult secondResult = secondQuery.evaluate();
			try {
				assertThat(second.closedLatch.await(3, TimeUnit.SECONDS))
						.as("a blocked close from one expired result must not stall another deadline")
						.isTrue();
				assertThat(first.closed).isFalse();
			} finally {
				secondResult.close();
			}
		} finally {
			releaseFirstClose.countDown();
			firstResult.close();
		}
	}

