	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void explicitCloseDefersDelegateCleanupUntilActiveCallReturns() throws Exception {
		BlockingIteration iteration = new BlockingIteration();
		when(sailConnection.evaluate(any(), any(), any(), anyBoolean())).thenAnswer(invocation -> iteration);
		TupleQuery query = repositoryConnection.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o }");
		query.setMaxExecutionTime(MAX_EXECUTION_TIME_SECONDS);
		TupleQueryResult result = query.evaluate();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Boolean> hasNext = executor.submit(result::hasNext);
		try {
			assertThat(iteration.entered.await(3, TimeUnit.SECONDS)).isTrue();
			result.close();
			assertThat(iteration.closed).isFalse();
			iteration.release.countDown();
			assertThat(hasNext.get(3, TimeUnit.SECONDS)).isTrue();
			assertThat(iteration.closedLatch.await(2, TimeUnit.SECONDS)).isTrue();
			assertThat(iteration.closeCalls.get()).isEqualTo(1);
		} finally {
			iteration.release.countDown();
			result.close();
			executor.shutdownNow();
			assertThat(executor.awaitTermination(3, TimeUnit.SECONDS)).isTrue();
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void timeoutCancelsDelegateBeforeActiveNextAndRemoveDrain() throws Exception {
		for (DelegateOperation operation : List.of(DelegateOperation.NEXT, DelegateOperation.REMOVE)) {
			QueryExecutionDeadline deadline = QueryExecutionDeadline.start(500);
			CountDownLatch deadlineExpired = new CountDownLatch(1);
			deadline.onExpiration(deadlineExpired::countDown);
			BlockingCallIteration delegate = new BlockingCallIteration(operation);
			DeadlineOperationTestIteration iteration = new DeadlineOperationTestIteration(delegate, deadline);
			ExecutorService executor = Executors.newSingleThreadExecutor();
			Future<?> call = executor.submit(() -> invoke(iteration, operation));
			try {
				assertThat(delegate.entered.await(3, TimeUnit.SECONDS)).isTrue();
				assertThat(deadlineExpired.await(3, TimeUnit.SECONDS)).isTrue();
				assertThat(delegate.closeEntered.await(2, TimeUnit.SECONDS)).isTrue();
				assertThat(delegate.closed).isFalse();

				delegate.release.countDown();
				assertThatThrownBy(() -> call.get(3, TimeUnit.SECONDS))
						.isInstanceOf(java.util.concurrent.ExecutionException.class)
						.hasRootCauseInstanceOf(QueryInterruptedException.class);
				assertThat(delegate.closedLatch.await(2, TimeUnit.SECONDS)).isTrue();
				assertThat(delegate.closeCalls.get()).isEqualTo(1);
			} finally {
				delegate.release.countDown();
				iteration.close();
				deadline.close();
				executor.shutdownNow();
				assertThat(executor.awaitTermination(3, TimeUnit.SECONDS)).isTrue();
			}
		}
	}

